func NormalizeEvent(event Event) Event {
	event.Kind = strings.ToLower(strings.TrimSpace(event.Kind))
	return event
}

func IsProbe(event Event) bool {
	return NormalizeEvent(event).Kind == "probe"
}

func Deliver(sink Sink, event Event) error {
	event = NormalizeEvent(event)
	if event.Kind == "probe" {
		return nil
	}
	return sink.Write(event)
}

